-- Citizens of Havenshire (28576, 28577)
-- Move the SmartAI handling to C++ (npc_citizen_of_havenshire) and move the
-- per-spawn waypoint paths from smart_scripts to creature_addon.

UPDATE `creature_template`
SET `AIName` = '', `ScriptName` = 'npc_citizen_of_havenshire'
WHERE `entry` IN (28576, 28577);

DELETE FROM `smart_scripts`
WHERE `entryorguid` IN (28576, 28577, 2857600, 2857601, 2857700, 2857701, -128910, -128911, -128912, -128913, -128914, -128915, -128916, -128917, -128918, -128919, -128920, -128922, -128924, -128926, -128927, -128928, -128929, -128930, -128934, -128935, -128948, -128954, -128958, -128959, -128960, -128961, -128962, -128963, -128964, -128965, -128966, -128967, -128968, -128970, -128973, -128976, -128978, -128979, -128980, -128981, -128986, -128991, -128992, -128993);

